def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                r2, c2 = r + dr, c + dc
                if 0 <= r2 < h and 0 <= c2 < w and grid[r2][c2] == color:
                    for er, ec, sr, sc in ((r, c, -dr, -dc), (r2, c2, dr, dc)):
                        nr, nc = er + sr, ec + sc
                        while 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg:
                            out[nr][nc] = color
                            nr, nc = nr + sr, nc + sc
    return out

